// Run: go test -fuzz=FuzzParse -fuzztime=60s ./parser
package parser

import "testing"

func FuzzParse(f *testing.F) {
	f.Add([]byte(`{"name": "demo"}`)) // seed inputs: a few real samples
	f.Add([]byte(""))
	f.Fuzz(func(t *testing.T, data []byte) {
		// Returning an error is fine. Panics, hangs and huge allocations are bugs.
		_, _ = Parse(data)
	})
}

// Setup: cargo install cargo-fuzz && cargo fuzz init && cargo fuzz add parse
// Run:   cargo +nightly fuzz run parse -- -max_total_time=60
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    // Errors are fine; panics and overflows are bugs.
    if let Ok(text) = std::str::from_utf8(data) {
        let _ = my_crate::parse(text);
    }
});

// Test dependency: com.code-intelligence:jazzer-junit (JUnit 5.9 or newer).
// "mvn test" replays saved crashes; to fuzz: JAZZER_FUZZ=1 mvn test -Dtest=ParserFuzzTest
package com.example;

import com.code_intelligence.jazzer.junit.FuzzTest;
import com.code_intelligence.jazzer.mutation.annotation.NotNull;

class ParserFuzzTest {
    @FuzzTest(maxDuration = "60s")
    void parse(@NotNull String input) {
        try {
            Parser.parse(input);
        } catch (ParseException expected) {
            // documented error; any other exception fails the test
        }
    }
}

